//! The registry of registered patches ("Registered patches" in `patch_nso.py`): static Rust tables instead of
//! `importlib`-loading `patches.py` files. The data tables (CUTS, OBS, CAPABILITIES, MATCH_CUTS) are generated by
//! `tools/gen_patch_tables.py` into `tables.rs`; of the code-valued tables (FRAME_STEP, STUBS, MATCH_FRAME_STEP,
//! MATCH_STUBS) the data around the stub functions (build IDs, rules, fingerprints) is generated too, and the stub
//! functions themselves are ported by hand in `stubs_games/`.

use crate::tables;

/// `(offset, original bytes, new bytes, reason)` of a registered cut (offset in the module image)
#[derive(Debug, Clone, Copy)]
pub struct Cut {
    pub off: i64,
    pub old: &'static str,
    pub new: &'static str,
    pub why: &'static str,
}

/// `(offset, number, original instruction word, reason)` of an observation gate
#[derive(Debug, Clone, Copy)]
pub struct Obs {
    pub off: i64,
    pub number: i64,
    pub word: &'static str,
    pub why: &'static str,
}

/// One function of a function-matched rule: its size, the fingerprints of the builds it is known on and the cuts
/// relative to its start (`delta` in `Cut::off`).
#[derive(Debug, Clone, Copy)]
pub struct FnRule {
    pub size: usize,
    pub fingerprints: &'static [&'static str],
    pub cuts: &'static [Cut],
}

/// A rule of `nso_match`: one function (`multi == false`, `functions.len() == 1`) or several that must change together.
#[derive(Debug, Clone, Copy)]
pub struct Rule {
    pub name: &'static str,
    pub multi: bool,
    pub functions: &'static [FnRule],
}

/// A rule of MATCH_FRAME_STEP / MATCH_STUBS (`nso_match.locate_stub`): the data around its stub function (`stubs_games`
/// has the function, at the rule's position in its module's list). Fingerprinted: the one function of `size` bytes with one
/// of the `fingerprints`, and `others`, more functions `(label, size, fingerprints)` found the same way. Anchored (`calls`
/// is set, size and fingerprints are empty): the one function that calls that imported symbol, checked by the port's `find`.
#[derive(Debug, Clone, Copy)]
pub struct MatchRule {
    pub name: &'static str,
    pub size: usize,
    pub fingerprints: &'static [&'static str],
    pub calls: Option<&'static str>,
    pub others: &'static [(&'static str, usize, &'static [&'static str])],
    /// MATCH_STUBS: `fps_required`, native engine frame targets stay off unless the stub sets `ctx.fps_ready`
    pub fps_required: bool,
}

/// the profile whose patch file registers FRAME_STEP for this build ID
pub fn frame_step_profile(build_id: &str) -> Option<&'static str> {
    tables::FRAME_STEP
        .iter()
        .find(|(b, _)| *b == build_id)
        .map(|(_, p)| *p)
}

/// the profile whose patch file registers STUBS for this build ID
pub fn stubs_profile(build_id: &str) -> Option<&'static str> {
    tables::STUBS
        .iter()
        .find(|(b, _)| *b == build_id)
        .map(|(_, p)| *p)
}

/// MATCH_FRAME_STEP rules of a game profile's module, in the file's order (empty: none)
pub fn match_frame_step_rules(profile: &str, module: &str) -> &'static [MatchRule] {
    tables::MATCH_FRAME_STEP
        .iter()
        .find(|(p, m, _)| *p == profile && *m == module)
        .map(|(_, _, r)| *r)
        .unwrap_or(&[])
}

/// MATCH_STUBS rules of a game profile's module, in the file's order (empty: none)
pub fn match_stub_rules(profile: &str, module: &str) -> &'static [MatchRule] {
    tables::MATCH_STUBS
        .iter()
        .find(|(p, m, _)| *p == profile && *m == module)
        .map(|(_, _, r)| *r)
        .unwrap_or(&[])
}

/// CUTS registered for a build ID (`None` when the build has no entry at all: an empty entry still counts as
/// registered, as in Python's `BUILD_ID not in PATCHES['CUTS']`)
pub fn cuts_for(build_id: &str) -> Option<&'static [Cut]> {
    tables::CUTS
        .iter()
        .find(|(b, _, _)| *b == build_id)
        .map(|(_, _, c)| *c)
}

pub fn obs_for(build_id: &str) -> &'static [Obs] {
    tables::OBS
        .iter()
        .find(|(b, _)| *b == build_id)
        .map(|(_, o)| *o)
        .unwrap_or(&[])
}

pub fn capabilities_for(build_id: &str) -> &'static [&'static str] {
    tables::CAPABILITIES
        .iter()
        .find(|(b, _)| *b == build_id)
        .map(|(_, c)| *c)
        .unwrap_or(&[])
}

/// SDK-wide (sdk_patches.py) and engine-wide (engine_patches.py) MATCH_CUTS of a module name, in file order
pub fn sdk_match_cuts(module: &str) -> Vec<Rule> {
    tables::SDK_MATCH_CUTS
        .iter()
        .filter(|(m, _)| *m == module)
        .flat_map(|(_, r)| r.iter().copied())
        .collect()
}

/// A game profile's MATCH_CUTS for a module
pub fn profile_match_cuts(profile: &str, module: &str) -> Vec<Rule> {
    tables::PROFILE_MATCH_CUTS
        .iter()
        .filter(|(p, _)| *p == profile)
        .flat_map(|(_, mods)| {
            mods.iter()
                .filter(|(m, _)| *m == module)
                .flat_map(|(_, r)| r.iter().copied())
        })
        .collect()
}
